package auth

import (
	"crypto/rand"
	"encoding/base64"
	"fmt"
	"testing"

	"golang.org/x/crypto/argon2"
)

// hashWith produces a hash using parameters other than the current defaults,
// so the "old parameters still verify" test does not depend on a hard-coded
// literal that would have to be regenerated by hand.
func hashWith(password string, memory, iterations uint32, parallelism uint8) string {
	salt := make([]byte, argonSaltLength)
	_, _ = rand.Read(salt)

	key := argon2.IDKey([]byte(password), salt,
		iterations, memory, parallelism, argonKeyLength)

	return fmt.Sprintf("$argon2id$v=%d$m=%d,t=%d,p=%d$%s$%s",
		argon2.Version, memory, iterations, parallelism,
		base64.RawStdEncoding.EncodeToString(salt),
		base64.RawStdEncoding.EncodeToString(key))
}

func decodeSegment(t *testing.T, segment string) string {
	t.Helper()
	raw, err := base64.RawURLEncoding.DecodeString(segment)
	if err != nil {
		t.Fatalf("decode segment: %v", err)
	}
	return string(raw)
}

func encodeSegment(s string) string {
	return base64.RawURLEncoding.EncodeToString([]byte(s))
}
